import SwiftUI

/// The pages, one case each with the parameters of its route; the app's
/// NavigationStack opens each through destination.
public enum Route: Hashable, Sendable {
    case board
    case document(id: String)
    case drafts
    case editor(id: String)
}

extension Route {
